import{_ as d,o as l,c as a,a2 as r}from"./chunks/framework.Dkj3JE0_.js";const b=JSON.parse('{"title":"对冲基金","description":"","frontmatter":{"title":"对冲基金"},"headers":[],"relativePath":"zh/blogs/CFA/C8 Alternative/M4 Hedge Fund.md","filePath":"zh/blogs/CFA/C8 Alternative/M4 Hedge Fund.md"}'),e={name:"zh/blogs/CFA/C8 Alternative/M4 Hedge Fund.md"};function i(o,t,h,n,s,u){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="对冲基金" tabindex="-1">对冲基金 <a class="header-anchor" href="#对冲基金" aria-label="Permalink to &quot;对冲基金&quot;">​</a></h1><h2 id="特征" tabindex="-1">特征 <a class="header-anchor" href="#特征" aria-label="Permalink to &quot;特征&quot;">​</a></h2><ul><li><p>法律/监管</p><ul><li>只面向达到最低收入或净资产要求的投资者</li><li>除<strong>流动性另类基金</strong>外，受到的监管约束远少于受监管的投资产品</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>**流动性另类基金（liquid alts）**是采用类似对冲基金策略的共同基金、封闭式基金或 ETF：</p><ul><li>每日可赎回</li><li>更广泛地向散户投资者推广</li><li>禁止收取业绩报酬</li><li>表现明显落后于同类策略的对冲基金。非流动性溢价现象难以移植到共同基金的形式中。</li></ul></div><ul><li>投资限制很少</li><li>投资范围广</li><li>投资风格激进</li><li>相对自由地使用杠杆</li><li>限制：锁定期、流动性闸门和退出窗口</li><li>费用结构相对较高：管理费和业绩报酬</li></ul></li></ul><h2 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h2><ul><li>单一管理人</li><li>多管理人 <ul><li>多策略</li><li>基金中的基金（FoF）</li></ul></li></ul><table tabindex="0"><thead><tr><th><strong>类别</strong></th><th><strong>策略</strong></th></tr></thead><tbody><tr><td>股票相关</td><td>- 股票多空</td></tr><tr><td></td><td>- 专门卖空与偏空策略</td></tr><tr><td></td><td>- 股票市场中性</td></tr><tr><td>事件驱动</td><td>- 并购套利</td></tr><tr><td></td><td>- 困境证券</td></tr><tr><td>相对价值</td><td>- 固定收益套利</td></tr><tr><td></td><td>- 可转债套利</td></tr><tr><td>机会型</td><td>- 全球宏观</td></tr><tr><td></td><td>- 管理期货</td></tr><tr><td>专业型</td><td>- 波动率交易</td></tr><tr><td></td><td>- 再保险/人寿保单贴现</td></tr><tr><td>多管理人</td><td>- 基金中的基金（FOF）</td></tr><tr><td></td><td>- 多策略对冲基金</td></tr></tbody></table><h2 id="策略" tabindex="-1">策略 <a class="header-anchor" href="#策略" aria-label="Permalink to &quot;策略&quot;">​</a></h2><h3 id="股票相关策略" tabindex="-1">股票相关策略 <a class="header-anchor" href="#股票相关策略" aria-label="Permalink to &quot;股票相关策略&quot;">​</a></h3><h4 id="多空组合的构建" tabindex="-1">多空组合的构建 <a class="header-anchor" href="#多空组合的构建" aria-label="Permalink to &quot;多空组合的构建&quot;">​</a></h4><table tabindex="0"><thead><tr><th>策略</th><th>多头头寸</th><th>空头头寸</th><th>现金</th><th>总敞口</th><th>净敞口</th></tr></thead><tbody><tr><td>纯多头</td><td>100</td><td>0</td><td>0</td><td>100</td><td>100</td></tr><tr><td>130/30 多头扩展</td><td>130</td><td>30</td><td>0</td><td>160</td><td>100</td></tr><tr><td>市场中性（低风险）</td><td>50</td><td>50</td><td>100</td><td>100</td><td>0</td></tr><tr><td>市场中性（高风险）</td><td>100</td><td>100</td><td>100</td><td>200</td><td>0</td></tr><tr><td>方向性（低风险）</td><td>80</td><td>40</td><td>60</td><td>120</td><td>40</td></tr><tr><td>净空头</td><td>40</td><td>100</td><td>160</td><td>140</td><td>-60</td></tr></tbody></table><ul><li>由于股市长期倾向于上涨，平均净多头敞口为 40–60</li><li>降低贝塔风险，并提供额外的阿尔法收益潜力</li><li>既可由有限合伙形式运作，也可通过流动性另类基金运作</li><li>流动性好、分散化，并且有透明的盯市定价</li></ul><h4 id="专门卖空" tabindex="-1">专门卖空 <a class="header-anchor" href="#专门卖空" aria-label="Permalink to &quot;专门卖空&quot;">​</a></h4><ul><li>专门卖空：只持有股票空头头寸。</li><li>偏空：结合以价值和指数为导向的多头敞口</li><li>激进做空：建立某只证券的空头头寸，然后公开发布做空报告</li></ul><h2 id="对冲基金策略对投资组合的贡献" tabindex="-1">对冲基金策略对投资组合的贡献 <a class="header-anchor" href="#对冲基金策略对投资组合的贡献" aria-label="Permalink to &quot;对冲基金策略对投资组合的贡献&quot;">​</a></h2>',14)])])}const _=d(e,[["render",i]]);export{b as __pageData,_ as default};
